int main() { toolchain_fingerprint_input_v1 base{"exe-hash", "clang-20", "sm_70", "/resource", "cuda-12", "driver-580", "plugin-3", {"-O2", "-fno-fast-math"}}; const auto identity = fingerprint_toolchain_v1(base); auto different = [&](auto mutate) { auto changed = base; mutate(changed); const auto other = fingerprint_toolchain_v1(changed); return other.low != identity.low || other.high != identity.high; }; if (!different([](auto& x){x.executable_content_hash += "x";}) || !different([](auto& x){x.version += "x";}) || !different([](auto& x){x.target += "x";}) || !different([](auto& x){x.resource_directory += "x";}) || !different([](auto& x){x.critical_flags.push_back("-g");}) || !different([](auto& x){x.runtime_identity += "x";}) || !different([](auto& x){x.driver_identity += "x";}) || !different([](auto& x){x.backend_plugin_revision += "x";})) return EXIT_FAILURE; auto reordered = base; std::reverse(reordered.critical_flags.begin(), reordered.critical_flags.end()); const auto same = fingerprint_toolchain_v1(reordered); if (same.low != identity.low || same.high != identity.high) return EXIT_FAILURE; const auto status = make_status_v1(compatibility_code_v1::toolchain_mismatch, lowering_stage_v1::executable_recipe); if (status.earliest_compatible_stage != lowering_stage_v1::physical_projection) return EXIT_FAILURE; std::cout << "validated stable fingerprint mutations and physical-projection resumption invalidation\n"; }
